rules = [
    (1, 'allow', 'tcp', '10.0.0.0/24', '192.168.1.10', 443),
    (2, 'deny', 'tcp', 'any', '192.168.1.10', 23),
    (3, 'allow', 'tcp', 'any', '192.168.1.10', 80),
    (4, 'deny', 'any', 'any', 'any', None)
]

def in_prefix(ip, prefix):
    if prefix == 'any':
        return True
    net, bits = prefix.split('/')
    bits = int(bits)
    a = list(map(int, ip.split('.')))
    b = list(map(int, net.split('.')))
    mask = (0xffffffff << (32 - bits)) & 0xffffffff
    aa = (a[0] << 24) | (a[1] << 16) | (a[2] << 8) | a[3]
    bb = (b[0] << 24) | (b[1] << 16) | (b[2] << 8) | b[3]
    return (aa & mask) == (bb & mask)

def match(rule, pkt):
    _, act, proto, src, dst, dport = rule
    if proto != 'any' and proto != pkt[4]:
        return False
    if not in_prefix(pkt[0], src):
        return False
    if dst != 'any' and dst != pkt[1]:
        return False
    if dport is not None and dport != pkt[3]:
        return False
    return True

packets = [
    ('10.0.0.5', '192.168.1.10', 50000, 443, 'tcp'),
    ('8.8.8.8', '192.168.1.10', 40000, 23, 'tcp'),
    ('10.0.0.5', '192.168.1.10', 50001, 22, 'tcp')
]

for p in packets:
    for r in rules:
        if match(r, p):
            print(r[0])
            break
